using EqlTracker.Core;

internal static class PetContributionTests
{
    internal static void Register(Action<string,Action> test)
    {
        void Check(bool ok){if(!ok)throw new Exception("Pet contribution/evidence assertion failed");}
        SpellReference Ref(string name)=>new(name,"https://eqlwiki.com/"+name.Replace(' ','_'),1,DateTime.UtcNow,"MAG","","","",""){Fields=new(){["skill"]="Alteration"}};
        ConnectedSpellIndex Index()=>new(new[]{Ref("Burnout III"),Ref("Test Heal"),Ref("Complete Heal"),Ref("Promised Renewal")});
        string Client(string name="Test Heal",int level=47,int duration=0,string effect="0|0|100|0|100|0")
        {var f=Enumerable.Repeat("0",171).ToArray();f[0]="123";f[1]=name;f[12]=duration.ToString();f[28]="1";f[30]="1";f[48]=level.ToString();f[167]=f[168]=f[169]="-1";f[170]=effect;return string.Join('^',f);}
        var now=new DateTime(2026,10,22,12,0,0,DateTimeKind.Local);
        ItemDefinition Weapon(string name="Test Weapon")=>new(){Key=Identity.Key(name),Name=name,MetadataComplete=true,Slots=["Primary","Secondary"],Classes=["ALL"],Stats=new(){["Damage"]=16,["Delay"]=22}};
        (Catalog,LoadoutProfile,PetBuild) Setup()
        {var item=Weapon();var catalog=new Catalog{Items=[item]};var owner=new LoadoutProfile{Classes=["MAG","BRD","SHD"],Level=50};var b=new PetBuild{PetType="Air",PetLevel=50,DualWield=true,Items=[new(){Position=1,ItemKey=item.Key,Name=item.Name,Slot="Primary",Rank=4,EquipmentVerified=true}]};return(catalog,owner,b);}
        foreach(var (rank,damage) in new[]{(0,16d),(1,17d),(4,22d),(10,32d)})test("Pet contributions: ranked loadout weapon +"+rank,()=>
        {var(c,o,b)=Setup();b.Items[0].Rank=rank;var result=PetDetailsStatistics.Project(b,o,c);var weapon=result.Loadout.Weapons[0];Check(weapon.Stats["Damage"]==damage&&weapon.Stats["Delay"]==22&&weapon.Stats["Ratio"]==damage/22&&weapon.State=="User-assigned hand"&&result.Loadout.Complete);});
        test("Pet contributions: dormant Secondary and empty hand are explicit",()=>{var(c,o,b)=Setup();b.DualWield=false;b.DormantSecondary=new(){Name="Dormant"};var s=PetDetailsStatistics.Project(b,o,c);Check(s.Loadout.Weapons[1].State=="Inactive");b.DormantSecondary=null;Check(PetDetailsStatistics.Project(b,o,c).Loadout.Weapons[1].State=="Empty");});
        test("Pet contributions: missing metadata never claims complete gear coverage",()=>{var(c,o,b)=Setup();c.Items[0].MetadataComplete=false;Check(!PetDetailsStatistics.Project(b,o,c).Loadout.Complete);c.Items.Clear();Check(!PetDetailsStatistics.Project(b,o,c).Loadout.Complete);});
        test("Pet contributions: names resolve before upgrade suffixes",()=>{var i=Index();Check(i.Resolve("Burnout III II") is{Canonical:"Burnout III",Rank:2});Check(i.Resolve("Monster Summoning II VIII") is{Canonical:"Monster Summoning II",Rank:8});Check(i.Resolve("Burnout III") is{Canonical:"Burnout III",Rank:0});Check(i.Resolve("Burnout III +13").Rank==13&&i.Resolve("Unknown Spell II").Rank==null);});
        test("Pet contributions: client spell records are atomic and versioned",()=>{var i=Index().WithClientLines([Client()],"fixture");Check(i.Resolve("Test Heal").Definition is{DirectHeal:100,Id:123}&&i.EvidenceVersion.Contains("fixture"));var rejected=Index().WithClientLines([Client(),"bad"],"bad");Check(rejected.Resolve("Test Heal").Definition?.DirectHeal==null&&!rejected.EvidenceVersion.Contains("client:bad"));});
        test("Pet contributions: cast attempts interrupted casts and buff transitions differ",()=>
        {var s=new ConnectedSpellState();var i=Index();ConnectedSpellEvidence.Attempt(s,new(){Time=now,PlayerCast="Burnout III II"},"cast","Hero",[],i);Check(ConnectedSpellEvidence.BuffHistory(s,"Hero").StartsWith("No retained"));ConnectedSpellEvidence.Attempt(s,new(){Time=now.AddSeconds(1),CastFailed=true},"failed","Hero",[],i);ConnectedSpellEvidence.Effect(s,new(){LogId="land",At=now.AddSeconds(2),Actor="Hero",Spells=["Burnout III"],State="Landing"},i);Check(s.History.Single(e=>e.Id=="land:spell-effect").Caster==""&&s.History.Single(e=>e.Id=="land:spell-effect").Rank==null);ConnectedSpellEvidence.Effect(s,new(){LogId="fade",At=now.AddSeconds(3),Actor="Hero",Spells=["Burnout III"],State="Fade"},i);Check(ConnectedSpellEvidence.BuffHistory(s,"Hero").Contains("Fade")&&ConnectedSpellEvidence.BuffHistory(s,"Hero").Contains("unresolved"));});
        test("Pet contributions: repeated observations are idempotent and restart-safe",()=>{var s=new ConnectedSpellState();var e=new SpellActivityEvidence{Id="x",At=now};Check(ConnectedSpellEvidence.Add(s,e)&&!ConnectedSpellEvidence.Add(s,e));var copy=EquipmentPositions.Copy(s);Check(copy.History.Count==1&&!ConnectedSpellEvidence.Add(copy,e));});
        test("Pet contributions: metadata checkpoint preserves log identity without rewinding the shared reader",()=>{var original=new FileCheckpoint{Offset=12345,Generation="stable",Path="synthetic.log",PrefixHash="prefix"};var copy=ConnectedSpellEvidence.InitialCheckpoint(original)!;Check(copy.Offset==0&&original.Offset==12345&&copy.Generation==original.Generation&&copy.PrefixHash==original.PrefixHash);});
        test("Pet contributions: historical metadata pass is isolated from research and stat state",()=>{var state=new ConnectedSpellState();var stats=new StatEvidenceState{Revision=4};var research=new PetResearchState();var before=PetResearch.Hash(new{stats,research});var lines=new[]{new TailLine("stable:0","[Thu Oct 22 12:00:00 2026] You begin casting Burnout III II."),new TailLine("stable:80","[Thu Oct 22 12:00:03 2026] Your Burnout III spell has worn off.")};ConnectedSpellEvidence.ReadMetadata(state,lines,"Hero",[],Index(),null);Check(state.History.Count==2&&PetResearch.Hash(new{stats,research})==before);ConnectedSpellEvidence.ReadMetadata(state,lines,"Hero",[],Index(),null);Check(state.History.Count==2);});
        test("Pet contributions: aliases resolve before rank and client variants preserve restrictions",()=>{var i=new ConnectedSpellIndex([Ref("Test Heal")],new Dictionary<string,string>{{"Healing Alias",EffectReferences.Key("Test Heal")}}).WithClientLines([Client("Test Heal II")],"fixture");Check(i.Resolve("Healing Alias III") is{Canonical:"Test Heal",Rank:3});Check(i.Resolve("Test Heal II").Definition is{DirectHeal:100,CombatSkill:false}&&i.Resolve("Test Heal II").Rank==2);});
        test("Pet contributions: successful landing retains correlated caster and upgrade rank",()=>{var s=new ConnectedSpellState();var i=Index();ConnectedSpellEvidence.Attempt(s,new(){Time=now,PlayerCast="Burnout III II"},"cast","Hero",[],i);ConnectedSpellEvidence.Effect(s,new(){LogId="land",At=now.AddSeconds(3),Actor="Pet",Spells=["Burnout III"],State="Landing"},i);Check(s.History[0] is{Caster:"Hero",Rank:2,Recipient:"Pet",Transition:"Landing"});});
        test("Pet contributions: buff history follows owned intervals and planned summon context",()=>{var p=new CharacterProfile{PetIdentities=[new(){Name="Repeat",Element="Air",From=now,Until=now.AddMinutes(1)},new(){Name="Repeat",Element="Fire",From=now.AddMinutes(1)}]};var s=new ConnectedSpellState();ConnectedSpellEvidence.Add(s,new(){Id="air",At=now.AddSeconds(2),Recipient="Repeat",Canonical="Air effect",Transition="Landing"});ConnectedSpellEvidence.Add(s,new(){Id="fire",At=now.AddMinutes(2),Recipient="Repeat",Canonical="Fire effect",Transition="Landing"});var text=ConnectedSpellEvidence.PetBuffHistory(s,new(){PetType="Air"},p);Check(text.Contains("Air effect")&&!text.Contains("Fire effect"));});
        test("Pet contributions: missing unnamed identity does not hide metadata gaps",()=>{var(c,o,b)=Setup();b.Items[0].ItemKey="";b.Items[0].Name="Unresolved physical item";Check(!PetDetailsStatistics.Project(b,o,c).Loadout.Complete);});
        test("Pet contributions: Water Backstab and owned observations exclude unrelated actors",()=>
        {var b=new PetBuild{PetType="Water",SummonSpell="Test",SummonRankKnown=false};var p=new CharacterProfile{PetIdentities=[new(){Name="Owned",From=now,Element="Water"}]};var fight=new Encounter{Events=[new(){Id="a",Actor="Owned",Owner="Pet",Time=now.AddSeconds(1),Ability="backstabs",Kind="Melee"},new(){Id="b",Actor="Other",Owner="Pet",Time=now.AddSeconds(1),Ability="backstabs",Kind="Melee"}]};var list=ConnectedSpellEvidence.PetAbilities(b,p,[fight],new());Check(list.Any(a=>a.Name=="Backstab"&&a.Kind=="Documented capability")&&list.Where(a=>a.Count>0).Sum(a=>a.Count)==1);});
        test("Pet contributions: focus is explicit for pets and excludes locked/conflicting effects",()=>
        {var item=new ItemDefinition{Key="idol",Name="Idol",Effects=["Focus: Improved Healing III"]};var c=new Catalog{Items=[item]};var e=new InventoryEntry{Name="Idol",ConfirmedItemKey="idol"};var pos=new EquipmentPosition{Slot="Primary",Knowledge=EquipmentKnowledge.Occupied,Item=e};var i=Index().WithClientLines([Client()],"fixture");Check(HealingFocusEvidence.Explain(i,"Test Heal",[pos],c,true,50,false).StartsWith("No active"));e.Name="Idol +1";e.Augments=[new(){EffectText="Focus: Improved Healing III"}];Check(HealingFocusEvidence.Explain(i,"Test Heal",[pos],c,true,50,false).Contains("101–120"));e.Name="Idol";Check(HealingFocusEvidence.Explain(i,"Test Heal",[pos],c,true,50,false).StartsWith("No active"));e.Name="Idol +1";e.Augments.Add(new(){EffectText="Focus: Improved Healing I"});Check(HealingFocusEvidence.Explain(i,"Test Heal",[pos],c,true,50,false).StartsWith("No active"));});
        test("Pet contributions: healing focus restrictions and unknown ranks do not yield flat bonuses",()=>
        {var item=new ItemDefinition{Key="idol",Name="Idol",Effects=["Focus: Improved Healing III"]};var c=new Catalog{Items=[item]};var pos=new EquipmentPosition{Slot="Primary",Knowledge=EquipmentKnowledge.Occupied,Item=new(){Name="Idol",ConfirmedItemKey="idol"}};var i=Index().WithClientLines([Client()],"fixture");Check(HealingFocusEvidence.Explain(i,"Complete Heal",[pos],c,false,50,false).Contains("Excluded"));Check(HealingFocusEvidence.Explain(i,"Test Heal",[pos],c,false,50,true).Contains("Excluded"));Check(HealingFocusEvidence.Explain(i,"Test Heal II",[pos],c,false,50,false).Contains("no expected range"));});
        foreach(var(method,expected)in new[]{("Drop","WAR · Named Mob — Component"),("Turn-in","WAR · Named Mob"),("Ground spawn","WAR · Component"),("Crafting","WAR · Component")})test("Pet contributions: compact objective "+method,()=>
        {var row=new ObjectiveRow{Class="Warrior",Item="Component",Mob="Named Mob",Zone="Zone",Needed=3,Sources=[new(){Zone="Zone",Mob="Named Mob",Method=method}],Instructions="Full instructions"};Check(CompactObjective.Text(row)==expected&&CompactObjective.Tooltip(row,true).Contains("need 3")&&CompactObjective.Tooltip(row,true).Contains("Full instructions"));});
    }
}
